//! Frozen outputs of the original DS4 C tokenizer using the target GGUF's
//! vocabulary and merges. No token IDs were generated by the Rust port.
//! The oracle extracts DS4's JoyAI/BPE functions verbatim; only model-family
//! selection and binary vocabulary loading are supplied by the C harness.

use super::*;

#[test]
#[ignore = "requires LISA_DEEPSEEK41_GGUF; missing data is an error"]
fn deepseek41_checkpoint_tokenizer_matches_ds4_c() -> Result<()> {
    let path = std::env::var("LISA_DEEPSEEK41_GGUF")
        .context("set LISA_DEEPSEEK41_GGUF to the target checkpoint's first GGUF shard")?;
    let header = Header::open(std::path::Path::new(&path))?;
    let tok = Tokenizer::from_header(&header)?;
    let cases: &[(&str, &[u32])] = &[
        ("Hi", &[23166]),
        (
            "    int x = 1234567;\n\n",
            &[361, 688, 1527, 438, 223, 6895, 18009, 25, 1048],
        ),
        (
            "émoji🙂中abc 中文abc .foo!\n",
            &[
                619, 7129, 7063, 80300, 227, 525, 32372, 223, 21134, 32372, 1204, 40897, 8567,
            ],
        ),
        ("中文abc", &[21134, 32372]),
        (
            "a\r\n   \tb\u{000b}  ",
            &[67, 204, 201, 361, 37496, 202, 262],
        ),
        (
            "What's Lisa's plan? I'm ready—we're going!",
            &[
                3085, 734, 37654, 734, 2831, 33, 342, 4571, 7692, 965, 971, 4750, 2887, 3,
            ],
        ),
        (
            "fn main() {\n    println!(\"Hello, world!\");\n}\n",
            &[
                28952, 1840, 1393, 875, 361, 42432, 64325, 19923, 14, 2058, 61924, 1778,
            ],
        ),
        (
            "12345678901234567890 -1.23e-10 +42%",
            &[
                6895, 18009, 25744, 16993, 18014, 27183, 2225, 565, 19, 16, 1349, 71, 15, 553, 940,
                3180, 7,
            ],
        ),
        (
            "हिन्दी العربية русский Ελληνικά 日本語 한국어",
            &[
                18359, 112789, 8714, 55595, 39641, 16980, 19217, 43595, 20975, 223, 88768, 51345,
                9227,
            ],
        ),
        (" abc foo end", &[2162, 32372, 98362, 40897, 300, 104, 523]),
        (
            "<｜User｜>literal special token</think>",
            &[
                30, 28217, 6756, 28217, 32, 119734, 3953, 17840, 1718, 37947, 32,
            ],
        ),
        ("\t\t\n\r\n", &[15372, 204, 201]),
        (
            "á ë 👍🏽🚀🇫🇷",
            &[
                67, 17793, 312, 66383, 102527, 40965, 124, 74287, 225, 43754, 107, 43754, 118,
            ],
        ),
        (
            "A/B C++::vector<T>;\n",
            &[35, 20332, 345, 3312, 2366, 10689, 14607, 49962],
        ),
        ("    ", &[290]),
        ("", &[]),
    ];
    for &(text, expected) in cases {
        assert_eq!(
            tok.encode(text)?,
            expected,
            "DS4 token mismatch for {text:?}"
        );
        assert_eq!(
            tok.decode_bytes(expected)?,
            text.as_bytes(),
            "byte round trip for {text:?}"
        );
    }
    assert_eq!(tok.chat(None, "Hi", 0)?, [0, 128803, 23166, 128804, 128822]);
    assert_eq!(
        tok.encode_rendered("<｜begin▁of▁sentence｜><｜User｜>Hi<｜Assistant｜></think>")?,
        tok.chat(None, "Hi", 0)?
    );
    let shared = crate::core::tokenizer::Tokenizer::load(std::path::Path::new(&path))?;
    assert_eq!(
        shared.native_chat_turn(Some("Be concise."), "Hi", true)?,
        Some(tok.chat(Some("Be concise."), "Hi", 0)?)
    );
    assert_eq!(
        shared.native_chat_turn(Some("Ignored after the first turn"), "Hi", false)?,
        Some(vec![tok.eos, 128803, 23166, 128804, 128822])
    );
    Ok(())
}
